package com.budgetfit.database;

import org.mindrot.jbcrypt.BCrypt;
import java.sql.*;
import java.util.ArrayList;
import java.util.List;

public class DatabaseHelper {
    private static final String DB_URL = "jdbc:sqlite:budgetfit.db";

    public static Connection getConnection() throws SQLException {
        Connection conn = DriverManager.getConnection(DB_URL);
        try (Statement stmt = conn.createStatement()) {
            stmt.execute("PRAGMA foreign_keys = ON;");
        } catch (SQLException e) {}
        return conn;
    }

    public static void initializeDatabase() {
        try (Connection conn = getConnection(); Statement stmt = conn.createStatement()) {
            stmt.execute("CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, pin_hash TEXT NOT NULL DEFAULT '', role TEXT DEFAULT 'user', monthly_income REAL DEFAULT 5000.0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, last_active DATETIME DEFAULT CURRENT_TIMESTAMP);");
            stmt.execute("CREATE TABLE IF NOT EXISTS transactions (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, category TEXT NOT NULL, item_name TEXT NOT NULL, budgeted_amount REAL DEFAULT 0.0, actual_amount REAL DEFAULT 0.0, paid INTEGER DEFAULT 0, recurring INTEGER DEFAULT 0, sender_receiver TEXT DEFAULT '', tx_type TEXT DEFAULT 'BUDGET', date DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));");
            stmt.execute("CREATE TABLE IF NOT EXISTS investments (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, symbol TEXT NOT NULL, shares REAL DEFAULT 0.0, avg_price REAL DEFAULT 0.0, current_price REAL DEFAULT 0.0, last_updated DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));");
            stmt.execute("CREATE TABLE IF NOT EXISTS system_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, action TEXT NOT NULL, log_date DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));");
            stmt.execute("CREATE TABLE IF NOT EXISTS goals (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, name TEXT NOT NULL, target_amount REAL NOT NULL, current_amount REAL DEFAULT 0.0, target_date TEXT DEFAULT '2026-12', FOREIGN KEY(user_id) REFERENCES users(id));");
            System.out.println("Database initialized successfully.");
        } catch (SQLException e) { e.printStackTrace(); }
    }
}

package com.budgetfit.dao;

import com.budgetfit.database.DatabaseHelper;
import com.budgetfit.model.User;
import org.mindrot.jbcrypt.BCrypt;
import java.sql.*;

public class UserDAO {
    public static User authenticate(String username, String password) {
        try (Connection conn = DatabaseHelper.getConnection(); PreparedStatement stmt = conn.prepareStatement("SELECT id, username, password_hash, pin_hash, role, monthly_income, last_active FROM users WHERE username = ?")) {
            stmt.setString(1, username);
            try (ResultSet rs = stmt.executeQuery()) {
                if (rs.next()) {
                    String storedHash = rs.getString("password_hash");
                    boolean matched = storedHash != null && storedHash.startsWith("$2a$") ? BCrypt.checkpw(password, storedHash) : storedHash.equals(password);
                    if (matched) return new User(rs.getInt("id"), username, rs.getString("role"), rs.getString("last_active"), rs.getDouble("monthly_income"), rs.getString("pin_hash"));
                }
            }
        } catch (SQLException e) { e.printStackTrace(); }
        return null;
    }

    public static boolean verifyPin(int userId, String pin) {
        try (Connection conn = DatabaseHelper.getConnection(); PreparedStatement stmt = conn.prepareStatement("SELECT pin_hash FROM users WHERE id = ?")) {
            stmt.setInt(1, userId);
            try (ResultSet rs = stmt.executeQuery()) {
                if (rs.next()) {
                    String storedHash = rs.getString("pin_hash");
                    return storedHash != null && storedHash.startsWith("$2a$") ? BCrypt.checkpw(pin, storedHash) : storedHash.equals(pin);
                }
            }
        } catch (SQLException e) { e.printStackTrace(); }
        return false;
    }
}

package com.budgetfit.dao;

import com.budgetfit.database.DatabaseHelper;
import com.budgetfit.model.TransactionEntry;
import java.sql.*;
import java.util.*;

public class TransactionDAO {
    public static List<TransactionEntry> loadTransactions(int userId, String monthStr) {
        List<TransactionEntry> list = new ArrayList<>();
        boolean filter = monthStr != null && !monthStr.equalsIgnoreCase("All Time") && !monthStr.isEmpty();
        String sql = "SELECT id, category, item_name, budgeted_amount, actual_amount, paid, recurring, sender_receiver, tx_type, date FROM transactions WHERE user_id = ?" + (filter ? " AND strftime('%Y-%m', date) = ?" : "") + " ORDER BY id ASC";
        try (Connection conn = DatabaseHelper.getConnection(); PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setInt(1, userId);
            if (filter) stmt.setString(2, monthStr);
            try (ResultSet rs = stmt.executeQuery()) {
                while (rs.next()) list.add(new TransactionEntry(rs.getInt("id"), rs.getString("category"), rs.getString("item_name"), rs.getDouble("budgeted_amount"), rs.getDouble("actual_amount"), rs.getInt("paid") == 1, rs.getInt("recurring") == 1, rs.getString("sender_receiver"), rs.getString("tx_type"), rs.getString("date"), false));
            }
        } catch (SQLException e) { e.printStackTrace(); }
        return list;
    }
}

package com.budgetfit.service;

import com.budgetfit.model.TransactionEntry;
import java.util.List;

public class BudgetService {
    public double calculateTotalBudget(List<TransactionEntry> entries) {
        return entries == null ? 0.0 : entries.stream().filter(e -> !e.isPlaceholder()).mapToDouble(TransactionEntry::getBudgetedAmount).sum();
    }
    public double calculateTotalActual(List<TransactionEntry> entries) {
        return entries == null ? 0.0 : entries.stream().filter(e -> !e.isPlaceholder()).mapToDouble(TransactionEntry::getActualAmount).sum();
    }
    public double calculateLeftToSpend(double monthlyIncome, double totalOutflow) {
        return Math.max(monthlyIncome - totalOutflow, 0.0);
    }
}

package com.budgetfit.controllers;

import com.budgetfit.dao.*;
import com.budgetfit.session.UserSession;
import javafx.fxml.FXML;
import javafx.scene.control.*;
import java.util.Optional;

public class AtmController {
    @FXML private Label atmBalanceLabel;
    @FXML private TextField depAmountField;

    private boolean promptForPin(String actionName) {
        TextInputDialog dialog = new TextInputDialog();
        dialog.setTitle("PIN Verification Required");
        dialog.setHeaderText("Authorize " + actionName);
        dialog.setContentText("Please enter your 4-digit ATM PIN:");
        Optional<String> result = dialog.showAndWait();
        return result.isPresent() && UserDAO.verifyPin(UserSession.getUserId(), result.get().trim());
    }

    @FXML private void handleDeposit() {
        double amount = Double.parseDouble(depAmountField.getText().trim());
        if (promptForPin("Cash Deposit of $" + amount)) {
            TransactionDAO.insertBankingTransaction(UserSession.getUserId(), "Income", "Cash Deposit", amount, "ATM Deposit", "DEPOSIT");
            refreshBalance();
        }
    }
}

package com.budgetfit.controllers;

import javafx.fxml.FXML;
import javafx.scene.layout.StackPane;
import javafx.scene.Parent;

public class DashboardController {
    @FXML private StackPane contentArea;
    @FXML private CheckBox darkModeBox;

    public void switchView(String fxmlFile) {
        try {
            Parent root = FXMLLoader.load(getClass().getResource(fxmlFile));
            if (darkModeBox.isSelected()) {
                root.getStylesheets().add(getClass().getResource("/css/dark-theme.css").toExternalForm());
            }
            contentArea.getChildren().setAll(root);
        } catch (Exception e) { e.printStackTrace(); }
    }
}
